import{_ as t,o,c as a,a6 as r}from"./chunks/framework.DIp0zHSV.js";const p=JSON.parse(`{"title":"LCARdS Theme Profiles for HA-LCARS","description":"The two LCARdS theme profiles HA-LCARS ships (LCARdS Red Accent and Blue Accent): one palette for Home Assistant's own screens, the HA-LCARS chrome and LCARdS cards, and how their colours are mapped.","frontmatter":{"description":"The two LCARdS theme profiles HA-LCARS ships (LCARdS Red Accent and Blue Accent): one palette for Home Assistant's own screens, the HA-LCARS chrome and LCARdS cards, and how their colours are mapped."},"headers":[],"relativePath":"configuration/ha-lcars-theme-profiles.md","filePath":"configuration/ha-lcars-theme-profiles.md","lastUpdated":1794184759000}`),s={name:"configuration/ha-lcars-theme-profiles.md"};function l(d,e,n,c,i,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="lcards-theme-profiles-for-ha-lcars" tabindex="-1">LCARdS Theme Profiles for HA-LCARS <a class="header-anchor" href="#lcards-theme-profiles-for-ha-lcars" aria-label="Permalink to &quot;LCARdS Theme Profiles for HA-LCARS&quot;">​</a></h1><p><strong><a href="https://github.com/th3jesta/ha-lcars" target="_blank" rel="noreferrer">HA-LCARS</a> includes two themes made for LCARdS: LCARS Picard [LCARdS Red Accent] and LCARS Picard [LCARdS Blue Accent].</strong> Pick one, and Home Assistant&#39;s own screens, the HA-LCARS chrome and your LCARdS cards all share one palette.</p><ul><li>They use the LCARdS colour palette (the <code>--lcards-*</code> variables), which the integration provides.</li><li>Home Assistant&#39;s core colour tokens (<code>--ha-color-*</code>), used by stock Home Assistant components, are mapped onto LCARdS palette colours, so the whole interface looks of a piece.</li><li>Every colour points at a palette variable rather than a fixed value, so alert mode colour shifts and the switch between light and dark mode reach everything.</li></ul><hr><h2 id="using-a-profile" tabindex="-1">Using a profile <a class="header-anchor" href="#using-a-profile" aria-label="Permalink to &quot;Using a profile&quot;">​</a></h2><p><strong>Install or update HA-LCARS, then pick one of the profiles as your theme.</strong> There is nothing to copy into <code>themes.yaml</code>.</p><ol><li>Install or update <a href="https://github.com/th3jesta/ha-lcars" target="_blank" rel="noreferrer">HA-LCARS</a>: the LCARdS profiles are part of its theme file, so update it if you don&#39;t see them.</li><li>In Home Assistant, open your <strong>Profile</strong> and pick <strong>LCARS Picard [LCARdS Red Accent]</strong> or <strong>LCARS Picard [LCARdS Blue Accent]</strong> as the theme.</li></ol><p>To make your own profile, use the <a href="./ha-lcars-theme-lab.html">HA-LCARS Theme Lab</a> in LCARdS Config: start from one of these profiles, change its palettes, and add the result to HA-LCARS.</p><hr><h2 id="available-profiles" tabindex="-1">Available Profiles <a class="header-anchor" href="#available-profiles" aria-label="Permalink to &quot;Available Profiles&quot;">​</a></h2><p><strong>Two profiles, differing in the accent colour Home Assistant&#39;s own buttons and controls use.</strong></p><table tabindex="0"><thead><tr><th>Profile name</th><th>Accent colour</th><th>Notes</th></tr></thead><tbody><tr><td><code>LCARS Picard [LCARdS Red Accent]</code></td><td>Orange and red (<code>--lcards-orange-*</code>)</td><td>Home Assistant&#39;s primary colour is the LCARdS orange family</td></tr><tr><td><code>LCARS Picard [LCARdS Blue Accent]</code></td><td>Blue (<code>--lcards-blue-*</code>)</td><td>Home Assistant&#39;s primary colour is the LCARdS blue family</td></tr></tbody></table><p>Both profiles have separate <strong>light</strong> and <strong>dark</strong> mode sections. They cover all 11 shades of Home Assistant&#39;s core colour tokens, and Home Assistant&#39;s <code>on-*</code>, <code>fill-*</code>, <code>border-*</code> and <code>surface-*</code> colours (the ones behind buttons, chips, form fields and dialogs).</p><hr><h2 id="how-the-colour-mapping-works" tabindex="-1">How the Colour Mapping Works <a class="header-anchor" href="#how-the-colour-mapping-works" aria-label="Permalink to &quot;How the Colour Mapping Works&quot;">​</a></h2><h3 id="home-assistant-core-colour-tokens" tabindex="-1">Home Assistant Core Colour Tokens <a class="header-anchor" href="#home-assistant-core-colour-tokens" aria-label="Permalink to &quot;Home Assistant Core Colour Tokens&quot;">​</a></h3><p><strong>Home Assistant&#39;s frontend has an 11-shade scale (05 to 95) for five colour families: <code>primary</code>, <code>neutral</code>, <code>orange</code>, <code>red</code> and <code>green</code>.</strong> Stock Home Assistant components use them.</p><ul><li>The profiles map each Home Assistant shade one to one onto the matching stop of the <a href="./../core/themes/#lcards-css-colour-palette">LCARdS 11-stop palette</a>.</li><li>The LCARdS palette grew from its original 7 canon stops to 11 for exactly this, so no two Home Assistant shades have to share one colour.</li></ul><p>The family mapping differs per profile:</p><table tabindex="0"><thead><tr><th>Home Assistant family</th><th>Red Accent profile</th><th>Blue Accent profile</th></tr></thead><tbody><tr><td><code>primary</code></td><td><code>--lcards-orange-*</code></td><td><code>--lcards-blue-*</code></td></tr><tr><td><code>neutral</code></td><td><code>--lcards-gray-*</code></td><td><code>--lcards-gray-*</code></td></tr><tr><td><code>orange</code></td><td><code>--lcards-yellow-*</code></td><td><code>--lcards-yellow-*</code></td></tr><tr><td><code>red</code></td><td><code>--lcards-orange-*</code></td><td><code>--lcards-orange-*</code></td></tr><tr><td><code>green</code></td><td><code>--lcards-green-*</code></td><td><code>--lcards-green-*</code></td></tr></tbody></table><h3 id="semantic-tokens-text-on-fill-contrast" tabindex="-1">Semantic Tokens (text-on-fill contrast) <a class="header-anchor" href="#semantic-tokens-text-on-fill-contrast" aria-label="Permalink to &quot;Semantic Tokens (text-on-fill contrast)&quot;">​</a></h3><p><strong>Both profiles also set Home Assistant&#39;s text and fill colours themselves, so button and chip text stays readable.</strong></p><ul><li>Home Assistant picks the text colour of buttons, chips and form fields (<code>--ha-color-on-*</code>) as a fixed tone of the same palette, such as &quot;tone 40 of whatever primary is&quot;, assuming any colour a theme puts there still reads well at that tone.</li><li>That doesn&#39;t hold equally for every hue: the LCARdS orange family has a narrower readable range of lightness than the blue one, so the Red Accent profile would otherwise get low-contrast button text.</li><li>The profiles therefore set the whole <code>on-*</code>, <code>fill-*</code>, <code>border-*</code> and <code>surface-*</code> layer, with every text and background pair checked against WCAG contrast and corrected where Home Assistant&#39;s default would fail. See <a href="./../development/ha-css-vars.html#layer-2-semantic-colour-tokens">ha-css-vars.md</a> for the technical detail.</li></ul><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="https://github.com/th3jesta/ha-lcars" target="_blank" rel="noreferrer">HA-LCARS repository</a></li><li><a href="./ha-lcars-theme-lab.html">HA-LCARS Theme Lab</a>: build your own profile</li><li><a href="./../core/themes/#lcards-css-colour-palette">LCARdS Colour Palette</a></li><li><a href="./../core/themes/">LCARdS Themes</a></li><li><a href="./../core/alert-mode.html">Alert Mode</a></li><li><a href="./../getting-started/installation.html">Installation</a></li></ul>',26)])])}const m=t(s,[["render",l]]);export{p as __pageData,m as default};
